// check_osd seed 1 replayed at the lab API boundary: every top-level call the JS check_osd makes into the lab objects
// (its inputs, format om-emu-osd-inputs/1, generated by checks/lib/osdcalls.mjs) is made again on a fresh lab with the
// same arguments, and each outcome's digest (return value, or exception class, message and notes) goes to
// env.replayStats.outcomes (bind.mjs outcomeSeen), where golden's output layer keeps it. At every check_osd group
// boundary (mark) the trace gets its mark, and the harness-side lab state must equal the one the generator saw (a
// replay that drifts from its own generation throws Divergence).
import { OsdLab } from '../src/lab/osd.mjs';
import { LabError, KeyError, AssertionError, ValueError, RuntimeError, FirmwareError, EngineError } from '../src/lab/errors.mjs';
import { hexBytes } from '../src/util/bytes.mjs';
import { spacedJson, asciiJson, normOut as out } from '../src/util/tracejson.mjs';
import { bind, outcomeSeen } from './bind.mjs';

export class Divergence extends Error {}
export const OSD_INPUTS_FORMAT = 'om-emu-osd-inputs/1';
const EXC = { KeyError, AssertionError, ValueError, RuntimeError, FirmwareError, EngineError };

function dec(v) {
  if (Array.isArray(v)) return v.map(dec);
  if (v !== null && typeof v === 'object') {
    if ('$bytes' in v) return hexBytes(v.$bytes);
    if ('$tuple' in v) return v.$tuple.map(dec);
    const o = {};
    for (const [k, x] of Object.entries(v)) o[k] = dec(x);
    return o;
  }
  return v;
}
export function labState(lab, sha) {
  const k = lab.kernel;
  return { surfaces: out(lab.surfaces ?? null, sha), init_errors: out(lab.init_errors ?? null, sha), isr_runs: lab.isr_runs ?? null,
    log_len: lab.log.length, irq_handlers: out(k.irq_handlers, sha), kernel_errors: out(k.errors, sha),
    events_sha: sha(asciiJson(out(k.events, sha))) };
}
// The signatures (positional order, keyword names, defaults) of every method check_osd calls at top level, bound by
// bind.mjs (shared with the session replayer): an unknown keyword, a missing argument or too many positionals throws
// instead of being guessed. Simulator.run's builtins / budget / on_stop have no counterpart in this replay: a call
// that gives one is refused.
const sig = (params, defaults, call, varkw = null) => ({ params, defaults, call, varkw });
const EMPTY = new Uint8Array(0);
const noExtras = (name, k, ps) => {
  for (const p of ps) if (Object.hasOwn(k, p) && k[p] !== ({ builtins: 0, budget: 0, on_stop: null })[p]) throw new Error(`osd replay: ${name}(${p}=...) is not replayed`);
};
const CALL = {
  'sim.registers': sig([], {}, (o) => o.registers()),
  'sim.reset': sig([], {}, (o, k) => o.reset(k.values), 'values'),
  'sim.write': sig(['address', 'data'], {}, (o, k) => o.write(k.address, k.data)),
  'sim.read': sig(['address', 'size'], {}, (o, k) => o.read(k.address, k.size)),
  'sim.u32': sig(['address'], {}, (o, k) => o.u32(k.address)),
  'sim.word': sig(['address', 'value'], {}, (o, k) => o.word(k.address, k.value)),
  'sim.run': sig(['stops', 'step', 'builtins', 'budget', 'on_stop'], { stops: [], step: false, builtins: 0, budget: 0, on_stop: null },
    (o, k) => { noExtras('sim.run', k, ['builtins', 'budget', 'on_stop']); return o.run(k.stops, k.step); }),
  'sim.packet': sig(['text'], {}, (o, k) => o.packet(k.text)),
  'lab.frame': sig(['function'], {}, (o, k) => o.frame(k.function)),
  'lab.finish': sig(['regs'], {}, (o, k) => o.finish(k.regs, k.results), 'results'),
  'lab.call': sig(['function', 'regs', 'stack', 'frame', 'limit'], { regs: null, stack: EMPTY, frame: null, limit: 5000 },
    (o, k) => o.call(k.function, k.regs, k.stack, k.frame, k.limit)),
  'lab.close': sig([], {}, (o) => o.close()),
  'lab.clear': sig(['buffer'], {}, (o, k) => o.clear(k.buffer)),
  'lab.driver': sig([], {}, (o) => o.driver()),
  'lab.alloc': sig(['data', 'align'], { align: 64 }, (o, k) => o.alloc(k.data, k.align)),
  'lab.rectangle': sig(['x', 'y', 'w', 'h', 'colour', 'layer', 'buffer'], { layer: 1, buffer: 0 },
    (o, k) => o.rectangle(k.x, k.y, k.w, k.h, k.colour, k.layer, k.buffer)),
  'lab.line': sig(['x', 'y', 'w', 'h', 'colour', 'layer', 'buffer'], { layer: 1, buffer: 0 },
    (o, k) => o.line(k.x, k.y, k.w, k.h, k.colour, k.layer, k.buffer)),
  'lab.block_copy': sig(['sx', 'sy', 'w', 'h', 'dx', 'dy', 'layer', 'buffer', 'dst_buffer'], { layer: 1, buffer: 0, dst_buffer: null },
    (o, k) => o.block_copy(k.sx, k.sy, k.w, k.h, k.dx, k.dy, k.layer, k.buffer, k.dst_buffer)),
  'lab.bitmap': sig(['x', 'y', 'address', 'lut', 'layer', 'buffer', 'width', 'height'], { lut: null, layer: 1, buffer: 0, width: 0, height: 0 },
    (o, k) => o.bitmap(k.x, k.y, k.address, k.lut, k.layer, k.buffer, k.width, k.height)),
  'lab.outline': sig(['x', 'y', 'w', 'h', 'line', 'colour', 'plane', 'buffer'], { plane: 0, buffer: 0 },
    (o, k) => o.outline(k.x, k.y, k.w, k.h, k.line, k.colour, k.plane, k.buffer)),
  'lab.set_fifo_mode': sig(['on'], {}, (o, k) => o.set_fifo_mode(k.on)),
  'lab.set_palette': sig(['layer', 'colours', 'start'], { start: 0 }, (o, k) => o.set_palette(k.layer, k.colours, k.start)),
  'lab.record': sig(['buffer'], {}, (o, k) => o.record(k.buffer)),
  'lab.outside_brackets': sig([], {}, (o) => o.outside_brackets()),
  'engine.u32': sig(['offset'], {}, (o, k) => o.u32(k.offset)),
  'engine.register': sig(['offset'], {}, (o, k) => o.register(k.offset)),
  'engine.irq_line': sig([], {}, (o) => o.irq_line()),
  'engine.clear': sig([], {}, (o) => o.clear()),
  'engine.set_key_mode': sig(['mode'], {}, (o, k) => o.set_key_mode(k.mode)),
  'engine.key_mode': sig([], {}, (o) => o.key_mode()),
  'engine.key_hits': sig([], {}, (o) => o.key_hits()),
  'engine.error_total': sig([], {}, (o) => o.error_total()),
  'engine.exec_total': sig([], {}, (o) => o.exec_total()),
  'engine.errors': sig([], {}, (o) => o.errors()),
  'kernel.rtos_names': sig([], {}, (o) => o.rtos_names()),
};
export { CALL as OSD_CALLS };       // checks/lib/osdcalls.mjs binds the JS check's calls with the same table
// The keyword-only arguments of the two bracket actions (RecDrawing writes them as kwargs, never positionally).
const DRAWING = { 'drawing.enter': ['expect', 'errlog'], 'drawing.exit': ['raised', 'expect_errlog'] };

// env as for scenarios/kernel.mjs, plus currentSession() (its tracer when tracing). env.replayStats (optional):
// outcomes as above; checkMs accumulates the replay's own outcome normalisation and lab-state comparison (not harness
// work).
export function replay(env, doc) {
  if (doc.format !== OSD_INPUTS_FORMAT) throw new Error(`osd inputs format ${doc.format}, want ${OSD_INPUTS_FORMAT}`);
  const sha = (b) => env.createHash('sha256').update(b).digest('hex');
  const actions = doc.actions;
  doc.decoded ??= actions.map((a) => [dec(a[3]), dec(a[4])]);       // the arguments, decoded once
  const clock = env.clock ?? (() => performance.now());
  const rs = env.replayStats ?? { checkMs: 0 };
  let lab = null, st = null;
  const tracer = () => env.currentSession?.()?.tracer ?? null;
  const frameRaised = (e, expect) => {
    const tr = tracer();
    if (tr && e instanceof LabError) tr.events.push(['frame', { raised: e.name, expect: [...expect], planes: tr.planes() }]);
  };
  for (let i = 0; i < actions.length; i++) {
    const [seq, target, method, , rawKwargs] = actions[i];
    const [args, kwargs] = doc.decoded[i];
    if (env.onAction) env.onAction(i, actions[i]);
    if (target === 'mark') {
      const tr = tracer();
      if (tr) {
        tr.lab = lab;
        const devices = tr.devices();
        tr.events.push(['mark', method, method.startsWith('end ')
          ? { result: rawKwargs.result, devices, planes: tr.planes(), log_len: lab.log.length } : { devices }]);
      }
      const c0 = clock();
      const state = labState(lab, sha), same = JSON.stringify(state) === JSON.stringify(rawKwargs.lab_state);
      rs.checkMs += clock() - c0;
      if (!same) {
        const d = new Divergence(`action ${seq} mark ${method}: lab state ${JSON.stringify(state).slice(0, 800)} != generated ${JSON.stringify(rawKwargs.lab_state).slice(0, 800)}`);
        d.seq = seq; d.method = 'mark ' + method; d.got = state; d.want = rawKwargs.lab_state;
        throw d;
      }
      continue;
    }
    let got;
    try {
      let result = null;
      if (target === 'ctor' || method === 'log.clear') bind(`${target}.${method}`, [], args, kwargs);
      else if (Object.hasOwn(DRAWING, method)) {
        if (args.length) throw new Error(`osd replay: lab.${method} takes its arguments as keywords only`);
        bind(`lab.${method}`, DRAWING[method], [], kwargs);
      }
      if (target === 'ctor') lab = new OsdLab(env);
      else if (method === 'log.clear') lab.log.length = 0;
      else if (method === 'drawing.enter') {
        const tr = tracer();
        if (tr) tr.lab = lab;
        lab.engine.lastRaw = null;
        try { st = lab.drawing_enter(kwargs.expect, kwargs.errlog); } catch (e) { frameRaised(e, kwargs.expect); throw e; }
      } else if (method === 'drawing.exit') {
        const s0 = st;
        st = null;
        s0.frame.expect_errlog = kwargs.expect_errlog;
        const raised = kwargs.raised;
        try {
          if (raised) lab.drawing_exit(s0, new EXC[raised[0]](raised[1]));
          const frame = lab.drawing_exit(s0, null), tr = tracer();
          if (tr) {
            const rows = lab.engine.lastRaw ?? [];
            tr.events.push(['frame', { result: frame.result, command_total: frame.command_total, error_total: frame.error_total,
              errors: frame.errors.map((e) => e.name), key_hits: frame.key_hits,
              errlog: frame.errlog.map(([c]) => '0x' + c.toString(16).padStart(8, '0')), logged: rows.length,
              exec_rows_sha: sha(spacedJson(rows)), expect: [...s0.expect], planes: tr.planes() }]);
          }
        } catch (e) { frameRaised(e, s0.expect); throw e; }
      } else {
        const obj = { lab, sim: lab?.sim, engine: lab?.engine, kernel: lab?.kernel }[target];
        const name = `${target}.${method}`;
        if (!Object.hasOwn(CALL, name)) throw new Error(`osd replay: no adapter for ${name}`);
        const { params, defaults, call, varkw } = CALL[name];
        result = call(obj, bind(name, params, args, kwargs, { defaults, varkw }));
      }
      const c0 = clock();
      got = { ret: out(result, sha) };
      rs.checkMs += clock() - c0;
    } catch (e) {
      if (!(e instanceof LabError)) throw e;
      got = { raise: [e.name, e.message, e.notes] };
    }
    outcomeSeen(env, got);
  }
  return 0;
}
